{
  "sql": "SELECT CASE WHEN dias_retraso <= 0 THEN 'a_tiempo' WHEN dias_retraso <= 3 THEN '1-3' WHEN dias_retraso <= 7 THEN '4-7' WHEN dias_retraso <= 14 THEN '8-14' ELSE '15+' END AS rango_retraso, COUNT(*) AS pedidos, ROUND(SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS pct_2_o_menos, (SELECT ROUND(SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) FROM vw_entregas_retrasos WHERE dias_retraso <= 0) AS pct_2_o_menos_a_tiempo FROM vw_entregas_retrasos WHERE order_status = 'delivered' AND order_purchase_timestamp IS NOT NULL AND order_delivered_customer_date IS NOT NULL AND review_score IS NOT NULL GROUP BY rango_retraso HAVING pct_2_o_menos >= 2 * (SELECT pct_2_o_menos_a_tiempo FROM (SELECT ROUND(SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS pct_2_o_menos_a_tiempo FROM vw_entregas_retrasos WHERE dias_retraso <= 0))"
}
